import sys


def divisor_count(n):
    count = 0
    for d in range(1, n + 1):
        if n % d == 0:
            count += 1
    return count


def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    out = []
    for k in range(1, q + 1):
        x = int(data[k])
        p = x
        while divisor_count(p) != 2:
            p -= 1
        r = x
        while divisor_count(r) != 2:
            r += 1
        out.append(str(r - p))
    print("\n".join(out))


main()

