import sys


def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def main():
    data = sys.stdin.buffer.read().split()
    q = int(data[0])
    out = []
    for k in range(1, q + 1):
        x = int(data[k])
        p = x
        while not is_prime(p):
            p -= 1
        r = x
        while not is_prime(r):
            r += 1
        out.append(str(r - p))
    sys.stdout.write("\n".join(out) + "\n")


main()
